from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
d=json.loads((R/'errors.json').read_text()); rows=d['errors'];sources=[]
def source(url,title,kind,product,access,coverage,trust):
    if any(s['url']==url for s in sources): return
    ids=[r['id'] for r in rows if url in r['source_urls']]
    sources.append(dict(url=url,title=title,type=kind,product=product,access=access,coverage=coverage,case_ids=ids,case_count=len(ids),trust=trust,checked_on='2026-10-30'))
